<?php use App\Core\Authorization;use App\Core\Csrf;$canPay=Authorization::allows('tuition.record_payment');$canManage=Authorization::allows('tuition.manage'); ?>
<div class="page-heading"><div><p class="eyebrow">Student ledger · <?=e($assessment['student_no'])?></p><h1><?=e($assessment['student_name'])?></h1><p><?=e($assessment['description'])?> · <?=e($assessment['school_year'])?><?= $assessment['term_name']?' · '.e($assessment['term_name']):''?></p></div><a class="button" href="<?=e(url('/tuition'))?>">Back to tuition</a></div>
<div class="grid three tuition-summary"><article class="stat-card"><span>Assessed</span><strong><?=e($currency)?> <?=number_format((float)$assessment['amount'],2)?></strong><small>Due <?=e($assessment['due_date']?:'date not set')?></small></article><article class="stat-card"><span>Paid</span><strong><?=e($currency)?> <?=number_format((float)$assessment['paid_amount'],2)?></strong><small>Confirmed collections</small></article><article class="stat-card"><span>Balance</span><strong><?=e($currency)?> <?=number_format((float)$assessment['balance'],2)?></strong><small><span class="badge"><?=e($assessment['status'])?></span></small></article></div>
<section class="card table-card fee-breakdown"><div class="table-heading"><div><h2>Fee breakdown</h2><small>Assessment categories</small></div></div><table><thead><tr><th>Tuition</th><th>Entrance fee</th><th>PACES</th><th>Closing fee</th><th>Shuttle</th><th>Total</th></tr></thead><tbody><tr><?php foreach(['tuition_fee_amount','entrance_fee_amount','paces_fee_amount','closing_fee_amount','shuttle_fee_amount'] as $key):?><td><?=e($currency)?> <?=number_format((float)$assessment[$key],2)?></td><?php endforeach;?><td><strong><?=e($currency)?> <?=number_format((float)$assessment['amount'],2)?></strong></td></tr></tbody></table></section>
<div class="detail-grid tuition-actions"><?php if($canPay&&$assessment['status']==='open'&&(float)$assessment['balance']>0):?><section class="card form-section"><h2>Record payment</h2><form method="post" action="<?=e(url('/tuition/'.$assessment['id'].'/payments'))?>" class="stack-form"><?=Csrf::field()?><div class="grid two"><label>Amount<input required type="number" name="amount" min="0.01" max="<?=e((string)$assessment['balance'])?>" step="0.01"></label><label>Payment for<select required name="payment_for"><?php foreach(['tuition'=>'Tuition','entrance_fee'=>'Entrance fee','paces'=>'PACES','closing_fee'=>'Closing fee','shuttle'=>'Shuttle','other'=>'Other'] as $value=>$label):?><option value="<?=$value?>"><?=e($label)?></option><?php endforeach;?></select></label><label>Payment date<input required type="date" name="paid_on" value="<?=e(date('Y-m-d'))?>"></label><label>Receipt number<input name="receipt_no" placeholder="Leave blank to auto-generate"></label><label>Method<select name="payment_method"><?php foreach(['cash'=>'Cash','bank_transfer'=>'Bank transfer','card'=>'Card','cheque'=>'Cheque','other'=>'Other'] as $value=>$label):?><option value="<?=$value?>"><?=e($label)?></option><?php endforeach;?></select></label></div><label>Remarks<input name="remarks" maxlength="500"></label><button class="button primary">Record payment</button></form></section><?php endif;?><?php if($canManage):?><section class="card form-section"><h2>Assessment status</h2><p>Waive or cancel only assessments with no recorded payments.</p><form method="post" action="<?=e(url('/tuition/'.$assessment['id'].'/status'))?>" class="stack-form"><?=Csrf::field()?><label>Status<select name="status"><?php foreach(['open','waived','cancelled'] as $x):?><option value="<?=$x?>" <?=$assessment['status']===$x?'selected':''?>><?=e(ucfirst($x))?></option><?php endforeach;?></select></label><button class="button">Update status</button></form></section><?php endif;?></div>
<section class="card table-card section-card"><div class="table-heading"><div><h2>Payment history</h2><small><?=count($payments)?> receipts</small></div></div><table><thead><tr><th>Receipt</th><th>Paid on</th><th>Payment for</th><th>Amount</th><th>Method</th><th>Received by</th><th>Remarks</th><th></th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><strong><?=e($p['receipt_no'])?></strong></td><td><?=e($p['paid_on'])?></td><td><?=e(ucwords(str_replace('_',' ',$p['payment_for'])))?></td><td><?=e($currency)?> <?=number_format((float)$p['amount'],2)?></td><td><?=e(ucwords(str_replace('_',' ',$p['payment_method'])))?></td><td><?=e($p['receiver'])?></td><td><?=e($p['remarks'])?></td><td><a class="button small" href="<?=e(url('/tuition/'.$assessment['id'].'/payments/'.$p['id'].'/receipt'))?>">View receipt</a></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="8" class="empty">No payments recorded for this assessment.</td></tr><?php endif;?></tbody></table></section>
